/**
 * Задачи «мат в один ход» из двух источников:
 *  - реальные партии с Lichess (id вида 'yxtqU') — импортированы скриптом
 *    tools/import-mate-puzzles.mjs;
 *  - синтетический набор SCM1-0001..SCM1-0500 — прислан уже с пометкой
 *    «verified unique mate-in-1», но эта пометка сама по себе ничего не
 *    доказывает: импортёр tools/import-mate-puzzles-scm.mjs перепроверил
 *    все 500 собственным движком правил, а не поверил чужой метке. Тот же
 *    принцип, что у безопасного шаха и Премувов в этом репозитории.
 *
 * Обе группы проверены на одном: FEN валиден, ход белых, ход решения
 * легален, после него на доске мат. Синтетический набор проверен ещё и на
 * единственность решения — перебором вообще всех легальных ходов позиции
 * (упражнение принимает как верный только один конкретный uci, см.
 * taskFromSolution в reaction-logic.ts, — второй столь же матующий ход
 * означал бы, что верный ответ пользователя иногда засчитывался бы как
 * ошибка). Проверки повторяются автотестом tests/puzzles-mate.test.ts,
 * поэтому битая задача не доедет до сборки.
 */
export interface MatePuzzle {
  /**
   * Идентификатор задачи: 'yxtqU' и подобные — со страницы
   * lichess.org/training/<id> (см. matePuzzleUrl); 'SCM1-0001'..'SCM1-0500'
   * — внутренний синтетический набор, у него такой страницы нет.
   */
  id: string;
  /** Позиция, ход белых. */
  fen: string;
  /** Единственный верный ход — тот, что ставит мат. */
  uci: string;
  san: string;
  themes: string[];
}

